CREATE ROLE anon NOLOGIN;
CREATE ROLE api WITH LOGIN PASSWORD 'helloapi';
CREATE ROLE service_role WITH LOGIN PASSWORD 'helloservice';
CREATE ROLE authenticated NOLOGIN;

CREATE ROLE app WITH LOGIN PASSWORD 'helloapp';
GRANT anon, authenticated TO app;

GRANT anon TO api;
GRANT authenticated TO api;
GRANT service_role TO api;

GRANT CREATE ON DATABASE clairvoyance TO service_role;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE SCHEMA IF NOT EXISTS api;

ALTER ROLE api SET search_path TO api, auth, public;

GRANT USAGE ON SCHEMA auth TO anon, authenticated;
GRANT USAGE ON SCHEMA api TO anon, authenticated;
GRANT ALL ON SCHEMA auth TO service_role;
GRANT ALL ON SCHEMA api TO service_role;

GRANT CREATE ON SCHEMA api TO api;

GRANT USAGE ON SCHEMA public TO anon, authenticated, api, service_role;
GRANT CREATE ON SCHEMA public TO api, service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO anon;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE ON SEQUENCES TO anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA auth GRANT SELECT ON TABLES TO anon;
ALTER DEFAULT PRIVILEGES IN SCHEMA auth GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA auth GRANT ALL ON TABLES TO service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA api GRANT SELECT ON TABLES TO anon;
ALTER DEFAULT PRIVILEGES IN SCHEMA api GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA api GRANT ALL ON TABLES TO service_role;

ALTER DEFAULT PRIVILEGES IN SCHEMA auth GRANT USAGE ON SEQUENCES TO anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA api GRANT USAGE ON SEQUENCES TO anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA auth GRANT ALL ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA api GRANT ALL ON SEQUENCES TO service_role;

CREATE OR REPLACE FUNCTION public.set_authenticated_role() RETURNS void AS $$
BEGIN
  IF current_setting('request.jwt.claims', true) IS NOT NULL AND current_setting('request.jwt.claims', true) != '' THEN
    SET LOCAL role = 'authenticated';
  ELSE
    SET LOCAL role = 'anon';
  END IF;
END
$$ LANGUAGE plpgsql SECURITY INVOKER;

GRANT EXECUTE ON FUNCTION public.set_authenticated_role() TO anon, authenticated;
